    } else {
      ctx.ui.notify(`Resuming ${examResumeLabel(exam)}.`, "info");
    }
  } else {
    const scope = await resolveExamScope(book, parsed.value, ctx);
    if (!scope) return;
    const now = new Date().toISOString();
